-- Backend Engineering ("The Fracture") Act 6 -- "Identity" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as Act 1 (20260810040000_backend_act1_content.sql).
-- References world-be-6, whose narrative metadata was pre-authored in
-- 20260810045000_backend_acts2_10_and_arc2.sql.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be6', 'world-be-6', 'identity', '6A - Identity', 'A resident''s account filed a report they never made. Nothing was hacked -- a session that should have died weeks ago never actually did.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be6-1', 'campaign-be6', 'proving-who-you-are', 'Proving Who You Are', 'Authentication, password storage, and the sessions, cookies and tokens that carry proof of identity from one request to the next.', 1),
  ('operation-be6-2', 'campaign-be6', 'the-session-that-would-not-die', 'The Session That Would Not Die', 'Rotation, revocation, and the delegated-identity protocols behind every "log in with..." button.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be6-01', 'world-be-6', 'campaign-be6', 'operation-be6-1', 'authentication-vs-authorization', 'Authentication vs Authorization', 'A resident''s account filed a report they never made. No password was stolen. Untangling this starts with two questions that sound the same and are not: who are you, and what are you allowed to do.', 'intermediate', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"auth-vs-authz-sim"}'::jsonb, '{"xp":130,"credits":20}'::jsonb, false, 1),
  ('mission-be6-02', 'world-be-6', 'campaign-be6', 'operation-be6-1', 'password-hashing', 'Password Hashing', 'What a database actually stores instead of a password decides whether one breach stays contained or becomes a citywide problem.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be6-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"password-hashing-sim"}'::jsonb, '{"xp":130,"credits":20}'::jsonb, false, 2),
  ('mission-be6-03', 'world-be-6', 'campaign-be6', 'operation-be6-1', 'sessions', 'Sessions', 'A session that outlived the person using it by six and a half weeks. Learn how a session is supposed to live and die, then find where this one broke the rules.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be6-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"session-lifecycle-sim"}'::jsonb, '{"xp":135,"credits":22}'::jsonb, false, 3),
  ('mission-be6-04', 'world-be-6', 'campaign-be6', 'operation-be6-1', 'cookies', 'Cookies', 'The humble cookie is how a session ID actually travels with a browser -- and how it leaks, one missing flag at a time.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be6-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"cookie-attributes-sim"}'::jsonb, '{"xp":135,"credits":22}'::jsonb, false, 4),
  ('mission-be6-05', 'world-be-6', 'campaign-be6', 'operation-be6-1', 'jwt', 'JWT', 'Not every service trusts a session store. Some hand out a signed, self-contained token instead and expect it to prove itself.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be6-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"jwt-anatomy-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 5),
  ('mission-be6-06', 'world-be-6', 'campaign-be6', 'operation-be6-1', 'access-and-refresh-tokens', 'Access and Refresh Tokens', 'One token that never expires is a liability with your name on it. Learn why almost nobody ships just one.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be6-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"token-pair-sim"}'::jsonb, '{"xp":145,"credits":25}'::jsonb, false, 6),
  ('mission-be6-07', 'world-be-6', 'campaign-be6', 'operation-be6-2', 'token-rotation', 'Token Rotation', 'A refresh token used once is normal. The same refresh token used twice, from two different places, is the alarm going off.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be6-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"token-rotation-sim"}'::jsonb, '{"xp":160,"credits":28}'::jsonb, false, 7),
  ('mission-be6-08', 'world-be-6', 'campaign-be6', 'operation-be6-2', 'logout-and-revocation', 'Logout and Revocation', 'Clicking log out should mean something on the server, not just in the browser. For a lot of codebases, it quietly doesn''t.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be6-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"logout-revocation-sim"}'::jsonb, '{"xp":165,"credits":28}'::jsonb, false, 8),
  ('mission-be6-09', 'world-be-6', 'campaign-be6', 'operation-be6-2', 'oauth-2-0-concepts', 'OAuth 2.0 Concepts', 'Residents want to sign in with an identity they already trust. Learn the handoff that makes that possible without ever handing over a password.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be6-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"oauth2-flow-sim"}'::jsonb, '{"xp":170,"credits":30}'::jsonb, false, 9),
  ('mission-be6-10', 'world-be-6', 'campaign-be6', 'operation-be6-2', 'openid-connect', 'OpenID Connect', 'OAuth proves what an app can access. It was never built to prove who''s using it. OpenID Connect exists to close that exact gap.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be6-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"oidc-id-token-sim"}'::jsonb, '{"xp":175,"credits":30}'::jsonb, false, 10),
  ('mission-be6-11', 'world-be-6', 'campaign-be6', 'operation-be6-2', 'social-login-architecture', 'Social Login Architecture', 'Every "continue with..." button hides a real decision: how do you link an outside identity to an account you control, permanently and correctly?', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be6-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"social-login-sim"}'::jsonb, '{"xp":185,"credits":32}'::jsonb, false, 11),
  ('mission-be6-12', 'world-be-6', 'campaign-be6', 'operation-be6-2', 'the-stolen-identity', 'The Stolen Identity', 'The account that filed a report from thirty thousand feet. Every lesson this Act taught, aimed at one zombie session.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be6-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"stolen-identity-boss-sim"}'::jsonb, '{"xp":420,"credits":90,"badgeIds":["stolen-identity"],"skillXp":{"auth_and_identity":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be6-01', 1, 'mira', 'A resident filed a report last week. Except she didn''t -- she was on a flight to Geneva when it was submitted from her account.'),
  ('mission-be6-01', 2, 'forge', 'No exploit in the login flow. No leaked password we can find. Whoever filed that report had a perfectly valid, perfectly authenticated session. That''s the part that should worry you.'),
  ('mission-be6-01', 3, 'mira', 'Before we chase that, get the fundamentals straight. Authentication answers ''who are you.'' Authorization answers ''what are you allowed to do.'' Forge Division has watched more incidents get misdiagnosed by confusing those two than almost anything else.'),
  ('mission-be6-02', 1, 'forge', 'Whoever filed that report didn''t need to steal a password -- but let''s make sure nobody could. A password should never be recoverable from what a database stores, only checkable.'),
  ('mission-be6-03', 1, 'mira', 'Here''s the part that doesn''t add up. The account''s session was created six and a half weeks ago and logged in without a single re-authentication since. Sessions aren''t supposed to work like that.'),
  ('mission-be6-03', 2, 'mira', 'Walk through how a session is actually supposed to live and die. Then tell me where this one broke the rules.'),
  ('mission-be6-04', 1, 'forge', 'A session ID is useless if it can''t travel with the browser. Cookies are how it rides along -- and how it leaks, if you set them wrong.'),
  ('mission-be6-05', 1, 'mira', 'Not every service in this stack uses server-side sessions. Some hand the client a signed token instead and trust the token to prove itself. Learn to read one the way you''d read a passport.'),
  ('mission-be6-06', 1, 'forge', 'A token that proves who you are for the next thirty seconds is safe to lose. A token that proves it for thirty days is a liability. That tension is why nobody ships just one token.'),
  ('mission-be6-07', 1, 'mira', 'Issuing a refresh token once isn''t the hard part. The hard part is noticing the moment somebody else starts using yours.'),
  ('mission-be6-08', 1, 'forge', 'Here''s an uncomfortable question: when a user clicks ''log out,'' what actually happens on the server? For a lot of codebases, the honest answer is ''nothing.'''),
  ('mission-be6-09', 1, 'mira', 'City residents don''t want another password to remember. They want to hit ''continue with'' something they already trust. That handoff has a name, and it has rules.'),
  ('mission-be6-10', 1, 'forge', 'OAuth was built to answer ''can this app access my data.'' It was never built to answer ''who is this person.'' A whole extra layer exists just to fix that gap.'),
  ('mission-be6-11', 1, 'mira', 'Every ''continue with Google'' button hides a real architectural decision: how do you link an outside identity to an account you control, without ever getting that link wrong?'),
  ('mission-be6-12', 1, 'mira', 'This is it. The account that filed a report from a flight. I want to know exactly how that session outlived the person using it.'),
  ('mission-be6-12', 2, 'forge', 'I''ve pulled three pieces of evidence from the account''s history. Each one looks like it could explain the whole incident. Only one actually does.'),
  ('mission-be6-12', 3, 'mira', 'Judge each on its own. Does it, alone, explain why this session never died? Then tell me the one rule that would have killed it on schedule.'),
  ('mission-be6-12', 4, 'forge', '...one more thing, buried in the login service''s route table. The path that minted this exact session is registered as ''//session/login''. Doubled slash. It didn''t cause today''s incident. But it''s the same mark we keep finding.'),
  ('mission-be6-12', 5, 'mira', 'Same as every other time. Noted. Filed. It still isn''t the day we chase that thread down -- but that day is getting closer.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be6-01-o1', 'mission-be6-01', 1, 'Tell them apart', 'Decide whether a given check is about identity or about permission.'),
  ('mission-be6-01-o2', 'mission-be6-01', 2, 'Sort the checks', 'Sort each check into authentication or authorization.'),
  ('mission-be6-02-o1', 'mission-be6-02', 1, 'Hash it right', 'Match each password-storage concept to what it actually does.'),
  ('mission-be6-02-o2', 'mission-be6-02', 2, 'Spot the real risk', 'Find the evidence that explains why one breach became a citywide problem.'),
  ('mission-be6-03-o1', 'mission-be6-03', 1, 'Order the lifecycle', 'Put a session''s lifecycle in the order it''s supposed to happen.'),
  ('mission-be6-03-o2', 'mission-be6-03', 2, 'Diagnose the zombie session', 'Find the evidence that explains why this specific session outlived its expiry.'),
  ('mission-be6-04-o1', 'mission-be6-04', 1, 'Match the attribute', 'Match each cookie attribute to what it actually protects against.'),
  ('mission-be6-04-o2', 'mission-be6-04', 2, 'Find the exposed cookie', 'Two headers issue the same session ID. Find the version a script could still steal.'),
  ('mission-be6-05-o1', 'mission-be6-05', 1, 'Order the token', 'Put the three parts of a JWT in the order they appear in the token string.'),
  ('mission-be6-05-o2', 'mission-be6-05', 2, 'Find the missing claim', 'Find the evidence that explains why this token was still accepted weeks after it was issued.'),
  ('mission-be6-06-o1', 'mission-be6-06', 1, 'Why two tokens', 'Decide why services issue an access token and a refresh token instead of just one long-lived token.'),
  ('mission-be6-06-o2', 'mission-be6-06', 2, 'Match the properties', 'Match each property to the token type it actually describes.'),
  ('mission-be6-07-o1', 'mission-be6-07', 1, 'Catch the replay', 'Find the evidence that reveals a stolen refresh token being reused.'),
  ('mission-be6-08-o1', 'mission-be6-08', 1, 'Find the fake logout', 'Find the line that means this logout handler doesn''t actually revoke anything.'),
  ('mission-be6-08-o2', 'mission-be6-08', 2, 'Fix the revocation', 'Decide what a real logout needs to do that this one doesn''t.'),
  ('mission-be6-09-o1', 'mission-be6-09', 1, 'Order the handoff', 'Order the steps of a standard OAuth 2.0 authorization code flow.'),
  ('mission-be6-09-o2', 'mission-be6-09', 2, 'Match the role', 'Match each OAuth role to what it actually is.'),
  ('mission-be6-10-o1', 'mission-be6-10', 1, 'What OIDC adds', 'Decide what OpenID Connect actually adds on top of plain OAuth 2.0.'),
  ('mission-be6-10-o2', 'mission-be6-10', 2, 'Read the ID token', 'Find the claim that proves this token is specifically about identity, not just access.'),
  ('mission-be6-11-o1', 'mission-be6-11', 1, 'Find the account-linking bug', 'Find the evidence that explains how a resident''s social login created a second, disconnected account.'),
  ('mission-be6-12-o1', 'mission-be6-12', 1, 'Evidence Alpha', 'Judge whether this evidence, on its own, explains the zombie session.'),
  ('mission-be6-12-o2', 'mission-be6-12', 2, 'Evidence Bravo', 'Judge whether this evidence, on its own, explains the zombie session.'),
  ('mission-be6-12-o3', 'mission-be6-12', 3, 'Evidence Charlie', 'Judge whether this evidence, on its own, explains the zombie session.'),
  ('mission-be6-12-o4', 'mission-be6-12', 4, 'Fix the contract', 'State the rule that would have killed this session on schedule.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be6-01-o1-c1', 'mission-be6-01-o1', 1, 'multiple_choice', 'A request arrives with a perfectly valid, signed session token, but the endpoint returns 403 Forbidden when the user tries to delete another resident''s report. Which system made that call?', '{"question":"A request arrives with a perfectly valid, signed session token, but the endpoint returns 403 Forbidden when the user tries to delete another resident''s report. Which system made that call?","options":[{"id":"a","text":"Authentication, because the token was valid"},{"id":"b","text":"Authorization, because a valid identity was confirmed but the action wasn''t permitted"},{"id":"c","text":"Both -- they''re the same check"},{"id":"d","text":"Neither -- a 403 always means the server crashed"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be6-01-o2-c1', 'mission-be6-01-o2', 1, 'drag_and_drop', 'Sort each check into authentication or authorization.', '{"items":[{"id":"d1","text":"Verifying a password matches what''s on file"},{"id":"d2","text":"Confirming a session token hasn''t expired"},{"id":"d3","text":"Checking whether this user''s role allows deleting a report"},{"id":"d4","text":"Confirming a fingerprint matches an enrolled scan"},{"id":"d5","text":"Checking whether this report belongs to the requesting user"}],"targets":[{"id":"authentication","label":"Authentication"},{"id":"authorization","label":"Authorization"}]}'::jsonb, '{"correctMapping":{"d1":"authentication","d2":"authentication","d3":"authorization","d4":"authentication","d5":"authorization"}}'::jsonb),

  ('mission-be6-02-o1-c1', 'mission-be6-02-o1', 1, 'drag_and_drop', 'Match each password-storage concept to what it actually does.', '{"items":[{"id":"h1","text":"Hashing"},{"id":"h2","text":"Salting"},{"id":"h3","text":"Storing plaintext passwords"},{"id":"h4","text":"A slow, purpose-built hashing algorithm (e.g. bcrypt/argon2)"}],"targets":[{"id":"t1","label":"Turns a password into a one-way value that can be checked but never reversed"},{"id":"t2","label":"Adds random per-user data before hashing so identical passwords don''t produce identical hashes"},{"id":"t3","label":"Means a single database breach exposes every user''s real password immediately"},{"id":"t4","label":"Makes brute-forcing a stolen hash deliberately expensive, even at scale"}]}'::jsonb, '{"correctMapping":{"h1":"t1","h2":"t2","h3":"t3","h4":"t4"}}'::jsonb),
  ('mission-be6-02-o2-c1', 'mission-be6-02-o2', 1, 'investigation', 'Which piece of evidence explains why this breach turned into more than one compromised account?', '{"evidence":[{"id":"ev1","label":"Database export","detail":"users table stores password as plaintext varchar -- one row reads password: SunsetBlvd42"},{"id":"ev2","label":"Reused password report","detail":"38% of affected residents used the same password on at least one other city service"},{"id":"ev3","label":"Breach timeline","detail":"the leaked database was three years old and had not been actively queried in months"}],"question":"Which piece of evidence explains why this breach turned into more than one compromised account?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be6-03-o1-c1', 'mission-be6-03-o1', 1, 'interactive_diagram', 'Put the six stages of a session''s life in the order they''re supposed to happen.', '{"diagramId":"session-lifecycle","hotspots":[{"id":"login","label":"User authenticates successfully","explanation":"The session lifecycle can''t begin until an identity has actually been confirmed."},{"id":"create","label":"Server creates and stores the session","explanation":"The server creates a session record with an expiry and keeps it server-side."},{"id":"issue_id","label":"Server issues an opaque session ID","explanation":"The client gets a reference to the session, never the session data itself."},{"id":"attach","label":"Client attaches the ID to future requests","explanation":"Usually via a cookie sent automatically on every request to the domain."},{"id":"validate","label":"Server validates the ID on each request","explanation":"The server looks the ID up in its store and checks it hasn''t expired."},{"id":"destroy","label":"Session is destroyed","explanation":"On logout, or once its expiry passes, whichever comes first."}],"task":"Put the six stages of a session''s life in the order they''re supposed to happen."}'::jsonb, '{"correctOrderIds":["login","create","issue_id","attach","validate","destroy"]}'::jsonb),
  ('mission-be6-03-o2-c1', 'mission-be6-03-o2', 1, 'investigation', 'Which piece of evidence explains why this session was never cleaned up, no matter how much time passed?', '{"evidence":[{"id":"ev1","label":"Session store record","detail":"the expires_at column for this session is NULL"},{"id":"ev2","label":"Login timestamp","detail":"the session was created 46 days before the incident"},{"id":"ev3","label":"Cleanup job config","detail":"the nightly job that purges expired sessions runs a query filtering WHERE expires_at < now()"}],"question":"Which piece of evidence explains why this session was never cleaned up, no matter how much time passed?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be6-04-o1-c1', 'mission-be6-04-o1', 1, 'drag_and_drop', 'Match each cookie attribute to what it actually protects against.', '{"items":[{"id":"c1","text":"HttpOnly"},{"id":"c2","text":"Secure"},{"id":"c3","text":"SameSite=Strict"},{"id":"c4","text":"Max-Age"}],"targets":[{"id":"t1","label":"Blocks JavaScript from reading the cookie, limiting damage from an XSS payload"},{"id":"t2","label":"Ensures the cookie is only ever sent over an encrypted HTTPS connection"},{"id":"t3","label":"Stops the cookie from being sent along with requests that originate from another site"},{"id":"t4","label":"Sets how long the cookie -- and the session it points to -- should live"}]}'::jsonb, '{"correctMapping":{"c1":"t1","c2":"t2","c3":"t3","c4":"t4"}}'::jsonb),
  ('mission-be6-04-o2-c1', 'mission-be6-04-o2', 1, 'code_debugging', 'An injected script on the page can still read one of these session_id cookies via document.cookie. Which line is it?', '{"language":"http","code":"Set-Cookie: session_id=8f3a1c9e7d21; Path=/\nSet-Cookie: theme=dark; Path=/; Max-Age=31536000\nSet-Cookie: session_id=8f3a1c9e7d21; Path=/; Secure; HttpOnly; SameSite=Strict","question":"An injected script on the page can still read one of these session_id cookies via document.cookie. Which line is it?"}'::jsonb, '{"requiredLineIds":["Set-Cookie: session_id=8f3a1c9e7d21; Path=/"]}'::jsonb),

  ('mission-be6-05-o1-c1', 'mission-be6-05-o1', 1, 'interactive_diagram', 'Put the three parts of a JWT in the order they appear in the token string, separated by periods.', '{"diagramId":"jwt-structure","hotspots":[{"id":"header","label":"Header","explanation":"Base64url-encoded metadata: which algorithm signed this token."},{"id":"payload","label":"Payload","explanation":"Base64url-encoded claims -- the actual data about the user and the token itself, e.g. sub, iat, exp."},{"id":"signature","label":"Signature","explanation":"Proves the header and payload haven''t been altered since a trusted party signed them."}],"task":"Put the three parts of a JWT in the order they appear in the token string, separated by periods."}'::jsonb, '{"correctOrderIds":["header","payload","signature"]}'::jsonb),
  ('mission-be6-05-o2-c1', 'mission-be6-05-o2', 1, 'investigation', 'Which piece of evidence explains why this token had no natural expiration?', '{"evidence":[{"id":"ev1","label":"Decoded header","detail":"{\"alg\":\"HS256\",\"typ\":\"JWT\"}"},{"id":"ev2","label":"Decoded payload","detail":"{\"sub\":\"resident-4471\",\"iat\":1700000000}"},{"id":"ev3","label":"Server verification code","detail":"server checks the signature and the sub claim, then treats the token as valid"}],"question":"Which piece of evidence explains why this token had no natural expiration?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be6-06-o1-c1', 'mission-be6-06-o1', 1, 'multiple_choice', 'Why do most systems issue a short-lived access token alongside a longer-lived refresh token, instead of one token that just lasts a long time?', '{"question":"Why do most systems issue a short-lived access token alongside a longer-lived refresh token, instead of one token that just lasts a long time?","options":[{"id":"a","text":"Two tokens are simply a convention -- there''s no real reason"},{"id":"b","text":"It limits how long a stolen access token stays useful, while the refresh token -- used rarely and only against a trusted endpoint -- can be watched and revoked more carefully"},{"id":"c","text":"Refresh tokens exist only to slow down legitimate users"},{"id":"d","text":"Access tokens can''t be signed, so a second token type is required"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be6-06-o2-c1', 'mission-be6-06-o2', 1, 'drag_and_drop', 'Match each property to the token type it actually describes.', '{"items":[{"id":"p1","text":"Sent with every single API request"},{"id":"p2","text":"Sent only to the token endpoint, rarely"},{"id":"p3","text":"Short-lived, minutes at most"},{"id":"p4","text":"Long-lived, and needs to be stored more carefully as a result"},{"id":"p5","text":"Used directly to authorize an action"}],"targets":[{"id":"access","label":"Access token"},{"id":"refresh","label":"Refresh token"}]}'::jsonb, '{"correctMapping":{"p1":"access","p2":"refresh","p3":"access","p4":"refresh","p5":"access"}}'::jsonb),

  ('mission-be6-07-o1-c1', 'mission-be6-07-o1', 1, 'investigation', 'Which piece of evidence is the actual signal that this refresh token was stolen and reused?', '{"evidence":[{"id":"ev1","label":"Refresh token store","detail":"refresh_token_9f2c was used to mint a new access token at 14:02:11 from IP 203.0.113.7, then used again at 14:02:19 from IP 198.51.100.44"},{"id":"ev2","label":"Rotation policy","detail":"each refresh token is single-use: using it issues a new refresh token and immediately invalidates the old one"},{"id":"ev3","label":"User activity log","detail":"the account''s owner reports being logged out unexpectedly at 14:02"}],"question":"Which piece of evidence is the actual signal that this refresh token was stolen and reused?"}'::jsonb, '{"requiredEvidenceIds":["ev1"]}'::jsonb),

  ('mission-be6-08-o1-c1', 'mission-be6-08-o1', 1, 'code_debugging', 'This runs when a user clicks log out. Which line explains why their session token still works afterward?', '{"language":"javascript","code":"function logout(req, res) {\n  localStorage.removeItem(\"session_token\");\n  res.redirect(\"/login\");\n}","question":"This runs when a user clicks log out. Which line explains why their session token still works afterward?"}'::jsonb, '{"requiredLineIds":["  localStorage.removeItem(\"session_token\");"]}'::jsonb),
  ('mission-be6-08-o2-c1', 'mission-be6-08-o2', 1, 'multiple_choice', 'Given the logout handler only clears a token from the browser''s local storage, what''s actually missing for this to be a secure logout?', '{"question":"Given the logout handler only clears a token from the browser''s local storage, what''s actually missing for this to be a secure logout?","options":[{"id":"a","text":"Nothing -- the client no longer has the token, so it''s effectively logged out"},{"id":"b","text":"The server must also invalidate the token/session on its own side (revoke it, blacklist it, or delete the session record), or a copy of that same token keeps working anywhere else it exists"},{"id":"c","text":"The redirect to /login should happen before clearing the token"},{"id":"d","text":"Logout should never clear client-side storage at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be6-09-o1-c1', 'mission-be6-09-o1', 1, 'interactive_diagram', 'Order the steps of a standard OAuth 2.0 authorization code flow.', '{"diagramId":"oauth2-authorization-code-flow","hotspots":[{"id":"redirect","label":"Redirect to the authorization server","explanation":"The client redirects the user to the authorization server, requesting access to a specific scope."},{"id":"consent","label":"User authenticates and consents","explanation":"The user logs into the authorization server and approves the requested access."},{"id":"code","label":"Authorization code returned","explanation":"The authorization server redirects back to the client with a short-lived, one-time code."},{"id":"exchange","label":"Client exchanges the code for a token","explanation":"The client sends the code plus its own client secret to the token endpoint."},{"id":"access","label":"Client calls the resource server","explanation":"The client uses the returned access token to act on the user''s behalf."}],"task":"Order the steps of a standard OAuth 2.0 authorization code flow."}'::jsonb, '{"correctOrderIds":["redirect","consent","code","exchange","access"]}'::jsonb),
  ('mission-be6-09-o2-c1', 'mission-be6-09-o2', 1, 'drag_and_drop', 'Match each OAuth role to what it actually is.', '{"items":[{"id":"r1","text":"Resource owner"},{"id":"r2","text":"Client"},{"id":"r3","text":"Authorization server"},{"id":"r4","text":"Resource server"}],"targets":[{"id":"rt1","label":"The user who owns the data and can grant access to it"},{"id":"rt2","label":"The application requesting access on the user''s behalf"},{"id":"rt3","label":"Issues tokens after verifying the user and the requested access"},{"id":"rt4","label":"Hosts the protected data and accepts the access token as proof of permission"}]}'::jsonb, '{"correctMapping":{"r1":"rt1","r2":"rt2","r3":"rt3","r4":"rt4"}}'::jsonb),

  ('mission-be6-10-o1-c1', 'mission-be6-10-o1', 1, 'multiple_choice', 'A client has a valid OAuth access token for a resource server. On its own, what does that token prove about who the user is?', '{"question":"A client has a valid OAuth access token for a resource server. On its own, what does that token prove about who the user is?","options":[{"id":"a","text":"The token itself proves the user''s verified identity"},{"id":"b","text":"Nothing reliable -- an access token is meant to prove what the bearer can access, not who they are; OpenID Connect adds a separate, verifiable ID token specifically to answer that"},{"id":"c","text":"OAuth and OpenID Connect are two names for the same protocol"},{"id":"d","text":"The access token always contains the user''s email address"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be6-10-o2-c1', 'mission-be6-10-o2', 1, 'code_debugging', 'This is a decoded ID token, not an access token. Which line is the strongest evidence this token exists to describe a specific person, not to grant API access?', '{"language":"json","code":"{\n  \"iss\": \"https://accounts.nexuscity.io\",\n  \"sub\": \"resident-4471\",\n  \"aud\": \"forge-dispatch-client\",\n  \"exp\": 1700003600,\n  \"email\": \"r.chen@nexuscity.io\",\n  \"email_verified\": true\n}","question":"This is a decoded ID token, not an access token. Which line is the strongest evidence this token exists to describe a specific person, not to grant API access?"}'::jsonb, '{"requiredLineIds":["  \"email\": \"r.chen@nexuscity.io\","]}'::jsonb),

  ('mission-be6-11-o1-c1', 'mission-be6-11-o1', 1, 'investigation', 'Which piece of evidence explains why the login created a brand-new account instead of linking to the resident''s existing one?', '{"evidence":[{"id":"ev1","label":"Provider response","detail":"provider returns {\"sub\":\"g-88214\",\"email\":\"r.chen@nexuscity.io\"}"},{"id":"ev2","label":"App account-lookup code","detail":"the app looks up an existing account by matching the email address in the provider''s response"},{"id":"ev3","label":"Account history","detail":"the resident changed their email address on the city platform two months before their first social login attempt"}],"question":"Which piece of evidence explains why the login created a brand-new account instead of linking to the resident''s existing one?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be6-12-o1-c1', 'mission-be6-12-o1', 1, 'multiple_choice', 'Evidence Alpha: the session cookie was issued with Secure and HttpOnly set correctly, with no sign it was ever read by a script or sent over plaintext HTTP. Does this explain why the session never expired?', '{"question":"Evidence Alpha: the session cookie was issued with Secure and HttpOnly set correctly, with no sign it was ever read by a script or sent over plaintext HTTP. Does this explain why the session never expired?","options":[{"id":"a","text":"Yes -- correct cookie flags are exactly what caused it to stay alive"},{"id":"b","text":"No -- correct cookie attributes protect a session in transit and from script access; they say nothing about whether the session itself has an expiry"},{"id":"c","text":"Yes -- HttpOnly cookies never expire by design"},{"id":"d","text":"Unknowable without seeing the network traffic"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be6-12-o2-c1', 'mission-be6-12-o2', 1, 'multiple_choice', 'Evidence Bravo: the session''s record in the store has expires_at set to NULL, and the nightly cleanup job''s query only deletes rows WHERE expires_at < now(). Does this explain why the session never expired?', '{"question":"Evidence Bravo: the session''s record in the store has expires_at set to NULL, and the nightly cleanup job''s query only deletes rows WHERE expires_at < now(). Does this explain why the session never expired?","options":[{"id":"a","text":"No -- NULL just means the value hasn''t loaded yet"},{"id":"b","text":"Yes -- a session created with no expiry at all will never satisfy a WHERE expires_at < now() filter, so it is functionally immortal until someone manually removes it"},{"id":"c","text":"No -- cleanup jobs never affect whether a session is still valid"},{"id":"d","text":"Unknowable without seeing who created the session"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be6-12-o3-c1', 'mission-be6-12-o3', 1, 'multiple_choice', 'Evidence Charlie: the account''s last successful login was 46 days before the incident. Does this fact, by itself, explain why the session was still valid?', '{"question":"Evidence Charlie: the account''s last successful login was 46 days before the incident. Does this fact, by itself, explain why the session was still valid?","options":[{"id":"a","text":"Yes -- 46 days is inherently too long for any system"},{"id":"b","text":"No -- a timestamp alone says how old the session is, not why the system failed to enforce any limit on that age; the age is a symptom, not the mechanism"},{"id":"c","text":"Yes -- all sessions expire automatically after 30 days by convention"},{"id":"d","text":"Unknowable without seeing the resident''s browser history"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be6-12-o4-c1', 'mission-be6-12-o4', 1, 'boss_encounter', 'Having judged all three pieces of evidence, state the one rule that would have prevented this incident.', '{"stages":[{"objectiveRef":"mission-be6-12-o1","label":"Evidence Alpha"},{"objectiveRef":"mission-be6-12-o2","label":"Evidence Bravo"},{"objectiveRef":"mission-be6-12-o3","label":"Evidence Charlie"}],"task":"Having judged all three pieces of evidence, state the one rule that would have prevented this incident: every session or token must be created with an enforced expiry from the start, and that expiry must be validated on every use -- not left to a best-effort cleanup job to eventually catch."}'::jsonb, '{"requiredObjectiveIds":["mission-be6-12-o1","mission-be6-12-o2","mission-be6-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be6-01-o1-c1', 'orientation', 'One of these systems already ran successfully before this check even happened.', 10, 1),
  ('mission-be6-01-o1-c1', 'concept', 'A valid token proves who is asking. It says nothing about what that person is allowed to do.', 20, 2),
  ('mission-be6-01-o1-c1', 'solution', 'b -- authentication already succeeded (the token was valid); authorization is the check that then said no.', 30, 3),
  ('mission-be6-01-o2-c1', 'orientation', 'Ask each item one question: does this prove identity, or does this decide permission?', 10, 1),
  ('mission-be6-01-o2-c1', 'solution', 'd1, d2, d4 -> authentication (proving who, or that the credential is valid). d3, d5 -> authorization (deciding what that identity may do).', 20, 2),

  ('mission-be6-02-o1-c1', 'orientation', 'Two of these are things you do; one is a mistake; one is a specific tool choice.', 10, 1),
  ('mission-be6-02-o1-c1', 'solution', 'h1 -> irreversible one-way transform, h2 -> per-user randomness against precomputed tables, h3 -> the failure mode itself, h4 -> deliberately slow, expensive-to-brute-force algorithm.', 20, 2),
  ('mission-be6-02-o2-c1', 'orientation', 'Look for the piece of evidence that is a cause, not a consequence.', 10, 1),
  ('mission-be6-02-o2-c1', 'concept', 'Reused passwords are a real problem, but they''re only exploitable here because of what the database actually stored.', 20, 2),
  ('mission-be6-02-o2-c1', 'solution', 'ev1 -- plaintext storage means the breach exposed real, usable passwords immediately, with no cracking required.', 30, 3),

  ('mission-be6-03-o1-c1', 'orientation', 'Nothing can be attached to a request until the server has actually created something to attach.', 10, 1),
  ('mission-be6-03-o1-c1', 'concept', 'The server has to know a session exists on its own end before it can hand out a reference to it.', 20, 2),
  ('mission-be6-03-o1-c1', 'tool_direction', 'Separate creation-side steps from validation-side steps -- the first three build the session, the last three are what happens on every later request.', 30, 3),
  ('mission-be6-03-o1-c1', 'solution', 'Login succeeds, the server creates and stores the session, the server issues an opaque ID to the client, the client attaches that ID to future requests, the server validates it against the store, and the session is destroyed on logout or expiry.', 40, 4),
  ('mission-be6-03-o2-c1', 'orientation', 'A cleanup job can only purge what it can actually query for.', 10, 1),
  ('mission-be6-03-o2-c1', 'concept', 'WHERE expires_at < now() silently skips any row where that column is NULL -- NULL never compares as less than anything in SQL.', 20, 2),
  ('mission-be6-03-o2-c1', 'solution', 'ev1 -- the session was created with no expiry set at all, so the nightly cleanup query''s WHERE expires_at < now() never matched it and it was never purged.', 30, 3),

  ('mission-be6-04-o1-c1', 'orientation', 'Three different attack surfaces: a malicious script, a network eavesdropper, a malicious cross-site request.', 10, 1),
  ('mission-be6-04-o1-c1', 'solution', 'HttpOnly -> blocks script access, Secure -> requires HTTPS, SameSite=Strict -> blocks cross-site requests, Max-Age -> controls lifetime.', 20, 2),
  ('mission-be6-04-o2-c1', 'orientation', 'document.cookie can only ever see cookies that don''t carry one specific flag.', 10, 1),
  ('mission-be6-04-o2-c1', 'concept', 'HttpOnly exists for exactly this reason -- to keep a cookie''s value out of reach of any JavaScript running on the page, malicious or not.', 20, 2),
  ('mission-be6-04-o2-c1', 'solution', 'The first Set-Cookie line issues session_id with no HttpOnly flag at all -- that''s the one a script could read.', 30, 3),

  ('mission-be6-05-o1-c1', 'orientation', 'One part proves nothing was tampered with, and it can only do that once the other two exist.', 10, 1),
  ('mission-be6-05-o1-c1', 'concept', 'Metadata about the signing method has to come first for a verifier to even know how to check it.', 20, 2),
  ('mission-be6-05-o1-c1', 'solution', 'header, then payload, then signature -- header.payload.signature.', 30, 3),
  ('mission-be6-05-o2-c1', 'orientation', 'A JWT carries its own expiry as a claim, or it doesn''t carry one at all.', 10, 1),
  ('mission-be6-05-o2-c1', 'concept', 'iat records when a token was issued. It says nothing about when it stops being valid -- that''s a separate claim entirely.', 20, 2),
  ('mission-be6-05-o2-c1', 'solution', 'ev2 -- the payload has an iat (issued-at) but no exp (expiration) claim, so there was never a deadline for the server to enforce.', 30, 3),

  ('mission-be6-06-o1-c1', 'orientation', 'Think about what''s actually lost if each token type gets stolen.', 10, 1),
  ('mission-be6-06-o1-c1', 'solution', 'b -- a stolen access token only works for a short window; a stolen refresh token is rarer to expose because it''s sent so infrequently, and it can be revoked.', 20, 2),
  ('mission-be6-06-o2-c1', 'orientation', 'Frequency of use and lifetime tend to move together here.', 10, 1),
  ('mission-be6-06-o2-c1', 'solution', 'Access: sent on every request, short-lived, used directly to authorize. Refresh: sent rarely, long-lived, needs stronger storage.', 20, 2),

  ('mission-be6-07-o1-c1', 'orientation', 'A single-use token being used successfully twice, from two different places seconds apart, is not supposed to be possible.', 10, 1),
  ('mission-be6-07-o1-c1', 'concept', 'The rotation policy is what makes the second use detectable at all -- without it, reuse would look identical to normal traffic.', 20, 2),
  ('mission-be6-07-o1-c1', 'solution', 'ev1 -- the same refresh token minting a new access token from two different IPs eleven seconds apart is reuse of a token that should have been single-use.', 30, 3),

  ('mission-be6-08-o1-c1', 'orientation', 'Ask what this function actually touches -- and what it never touches at all.', 10, 1),
  ('mission-be6-08-o1-c1', 'solution', 'localStorage.removeItem only clears the browser''s copy. The server-side session or token record is never told the user logged out, so it stays valid.', 20, 2),
  ('mission-be6-08-o2-c1', 'orientation', 'A copy of the token could exist anywhere the user was logged in -- another tab, another device, an attacker who copied it earlier.', 10, 1),
  ('mission-be6-08-o2-c1', 'solution', 'b -- real revocation has to happen on the server, invalidating the session/token itself, not just clearing the client''s reference to it.', 20, 2),

  ('mission-be6-09-o1-c1', 'orientation', 'Nothing can be exchanged for a token until the user has actually approved something.', 10, 1),
  ('mission-be6-09-o1-c1', 'concept', 'A code is a short-lived, one-time proof of consent -- it exists specifically so the access token itself is never passed through the browser''s address bar.', 20, 2),
  ('mission-be6-09-o1-c1', 'solution', 'Redirect to the authorization server, the user consents, an authorization code comes back, the client exchanges it for an access token, then the client uses that token against the resource server.', 30, 3),
  ('mission-be6-09-o2-c1', 'orientation', 'One of these is a person. The rest are servers, but they don''t do the same job.', 10, 1),
  ('mission-be6-09-o2-c1', 'solution', 'Resource owner: the user. Client: the app. Authorization server: issues tokens. Resource server: holds the data and checks the token.', 20, 2),

  ('mission-be6-10-o1-c1', 'orientation', 'An access token is a permission slip. A permission slip doesn''t have to say whose face is on it.', 10, 1),
  ('mission-be6-10-o1-c1', 'solution', 'b -- OAuth alone never guarantees identity; OpenID Connect layers an ID token on top specifically to answer ''who is this.''', 20, 2),
  ('mission-be6-10-o2-c1', 'orientation', 'sub is an identifier, but it''s opaque -- it could belong to a service as easily as a person.', 10, 1),
  ('mission-be6-10-o2-c1', 'concept', 'Look for a claim that only makes sense attached to an actual human being.', 20, 2),
  ('mission-be6-10-o2-c1', 'solution', 'The email claim -- a real, verified, human-readable identity attribute that an access token has no reason to carry at all.', 30, 3),

  ('mission-be6-11-o1-c1', 'orientation', 'Emails can change. Something else in that provider response is meant to be permanent.', 10, 1),
  ('mission-be6-11-o1-c1', 'concept', 'The provider''s sub claim is the stable, unique identifier for that identity -- an email is just an attribute that can be edited at any time.', 20, 2),
  ('mission-be6-11-o1-c1', 'solution', 'ev2 -- linking by email instead of the provider''s stable sub identifier means any email change breaks the link and creates a duplicate account.', 30, 3),

  ('mission-be6-12-o1-c1', 'orientation', 'Ask what each flag actually protects against, not just whether it''s present.', 10, 1),
  ('mission-be6-12-o1-c1', 'solution', 'b -- these attributes were all correctly set and are unrelated to whether the session itself has a lifespan.', 20, 2),
  ('mission-be6-12-o2-c1', 'orientation', 'Think about what a WHERE clause comparing against NULL actually returns in SQL.', 10, 1),
  ('mission-be6-12-o2-c1', 'solution', 'b -- NULL never satisfies expires_at < now(), so a session created without an expiry is invisible to the cleanup job forever.', 20, 2),
  ('mission-be6-12-o3-c1', 'orientation', 'A fact about elapsed time is not the same as a fact about enforcement.', 10, 1),
  ('mission-be6-12-o3-c1', 'solution', 'b -- the age alone doesn''t explain anything; the missing enforcement does.', 20, 2),
  ('mission-be6-12-o4-c1', 'orientation', 'Look at what all three judgments pointed away from, and the one thing none of them could substitute for.', 15, 1),
  ('mission-be6-12-o4-c1', 'solution', 'Every session or token needs an expiry enforced at creation time and checked on every use -- not a cleanup job, not correct cookie flags, not assumptions based on how old it looks. A missing expires_at/exp is the actual defect, and nothing else in this story fixes that.', 25, 2);
